Here's your expense tracker for November. Add an expense, pick a category, and the total and category bars update as you go. It keeps entries only while this page is open, so nothing is saved after you close it.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body{font-family:Segoe UI,Arial,sans-serif;margin:0;padding:16px;background:#f6f7f4;color:#222}
  h2{margin:0 0 12px;font-size:20px}
  .card{background:#fff;border-radius:12px;padding:14px;margin-bottom:12px;box-shadow:0 1px 3px rgba(0,0,0,.08)}
  .row{display:flex;gap:8px;flex-wrap:wrap}
  input,select,button{font:inherit;padding:8px;border:1px solid #ccc;border-radius:8px}
  input{flex:1;min-width:90px}
  button{background:#2f7d5b;color:#fff;border:none;cursor:pointer}
  button.x{background:none;color:#b00;padding:2px 8px}
  .big{font-size:28px;font-weight:600}
  .muted{color:#666;font-size:13px}
  .bar{height:10px;border-radius:5px;background:#2f7d5b;margin:3px 0 8px}
  .item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eee}
  .over{color:#b00}
</style>
</head>
<body>
<h2>Expenses: Nov 2026</h2>

<div class="card">
  <div class="muted">Spent this month</div>
  <div class="big" id="total">₹0</div>
  <div class="row" style="margin-top:8px;align-items:center">
    <span class="muted">Monthly budget (₹)</span>
    <input id="budget" type="number" value="50000">
  </div>
  <div id="left" class="muted" style="margin-top:6px"></div>
</div>

<div class="card">
  <div class="row">
    <input id="note" type="text" placeholder="What was it?">
    <input id="amt" type="number" placeholder="Amount (₹)">
    <select id="cat">
      <option>Food</option><option>Rent</option><option>Travel</option>
      <option>Bills</option><option>Shopping</option><option>Fun</option><option>Other</option>
    </select>
    <button id="add">Add</button>
  </div>
</div>

<div class="card">
  <b>By category</b>
  <div id="cats" style="margin-top:8px"></div>
</div>

<div class="card">
  <b>All entries</b>
  <div id="list" style="margin-top:6px"></div>
</div>

<script>
var items = [];
function fmt(n){ return "₹" + Number(n).toLocaleString("en-IN"); }
function render(){
  var total = 0, by = {};
  items.forEach(function(i){ total += i.amt; by[i.cat] = (by[i.cat]||0) + i.amt; });
  document.getElementById("total").textContent = fmt(total);
  var b = Number(document.getElementById("budget").value) || 0;
  var left = document.getElementById("left");
  if (b > 0) {
    var d = b - total;
    left.textContent = d >= 0 ? fmt(d) + " left of your budget" : fmt(-d) + " over your budget";
    left.className = d >= 0 ? "muted" : "muted over";
  } else { left.textContent = ""; }
  var cats = document.getElementById("cats");
  cats.innerHTML = "";
  Object.keys(by).sort(function(a,c){return by[c]-by[a];}).forEach(function(k){
    var w = total ? Math.round(by[k]/total*100) : 0;
    var d = document.createElement("div");
    d.innerHTML = "<div style='display:flex;justify-content:space-between'><span>" + k + "</span><span>" + fmt(by[k]) + " (" + w + "%)</span></div><div class='bar' style='width:" + w + "%'></div>";
    cats.appendChild(d);
  });
  if (!items.length) cats.innerHTML = "<span class='muted'>Nothing yet.</span>";
  var list = document.getElementById("list");
  list.innerHTML = "";
  items.slice().reverse().forEach(function(i){
    var r = document.createElement("div");
    r.className = "item";
    var s = document.createElement("span");
    s.textContent = i.note + " · " + i.cat;
    var right = document.createElement("span");
    right.textContent = fmt(i.amt) + " ";
    var x = document.createElement("button");
    x.className = "x"; x.textContent = "✕";
    x.onclick = function(){ items = items.filter(function(e){return e !== i;}); render(); };
    right.appendChild(x);
    r.appendChild(s); r.appendChild(right);
    list.appendChild(r);
  });
}
document.getElementById("add").onclick = function(){
  var a = Number(document.getElementById("amt").value);
  if (!a || a <= 0) return;
  items.push({
    note: document.getElementById("note").value.trim() || "Expense",
    amt: a,
    cat: document.getElementById("cat").value
  });
  document.getElementById("note").value = "";
  document.getElementById("amt").value = "";
  render();
};
document.getElementById("budget").oninput = render;
render();
</script>
</body>
</html>
```
